const NAME_TO_DIVISION = new Map(
  SECTOR_CATALOG.map(s => [s.name, String(s.nafCodes?.[0] || "").slice(0, 2)])
);

function keyFor(sector=""){
  const division = NAME_TO_DIVISION.get(String(sector).trim());
  return division || null;
}

export function marketBenchmark(sector=""){
  const key=keyFor(sector);
  return key && DATA[key] ? {key,...DATA[key]} : null;
}

export function marketMetric(market,key){
  return market?.[key] || null;
}

export const MARKET_SOURCE="Classeur BON Codes NAF — données 2024";
export const MARKET_COVERAGE=Object.keys(DATA).length;
export { DATA as MARKET_DATA };
